export const SPEED_DISTANCE_TIME_ACTIVITIES = [
{n:1,type:"mcq",micro:"Membandingkan kecepatan dari waktu tempuh",q:"Dua pelari berlari menempuh jarak yang sama, tetapi pelari A tiba lebih dulu daripada pelari B. Siapa yang berlari lebih cepat?",options:["Pelari A","Pelari B","Keduanya berlari dengan kecepatan yang sama"],answer:0,explain:"Untuk jarak yang sama, waktu tempuh yang lebih singkat menunjukkan kecepatan yang lebih tinggi.",hint:"Siapa yang membutuhkan waktu lebih sedikit untuk jarak yang sama?"},
{n:2,type:"mcq",micro:"Membandingkan kecepatan kendaraan",q:"Sebuah mobil menempuh jarak 100 km dalam waktu 2 jam. Sebuah motor menempuh jarak 100 km dalam waktu 3 jam. Kendaraan mana yang lebih cepat?",options:["Motor","Mobil","Keduanya sama cepatnya"],answer:1,explain:"Untuk jarak yang sama (100 km), waktu tempuh yang lebih singkat (2 jam) menunjukkan kecepatan yang lebih tinggi.",hint:"Kendaraan mana yang menempuh jarak yang sama dalam waktu yang lebih singkat?"},
{n:3,type:"mcq",micro:"Kecepatan tetap dan jarak bertambah",q:"Jika kamu berjalan dengan kecepatan tetap, apa yang terjadi pada jarak yang kamu tempuh seiring bertambahnya waktu?",options:["Jarak yang ditempuh tetap sama","Jarak yang ditempuh berkurang","Jarak yang ditempuh terus bertambah"],answer:2,explain:"Selama kamu terus bergerak dengan kecepatan tetap, jarak yang ditempuh terus bertambah seiring waktu.",hint:"Jika kamu terus berjalan tanpa berhenti, apakah jarak yang sudah kamu tempuh bertambah atau tetap?"},
{n:4,type:"mcq",micro:"Kecepatan lebih tinggi butuh waktu lebih sedikit",q:"Sebuah kereta bergerak lebih cepat daripada sepeda. Untuk menempuh jarak yang sama, kendaraan mana yang membutuhkan waktu lebih sedikit?",options:["Kereta","Sepeda","Keduanya membutuhkan waktu yang sama"],answer:0,explain:"Kendaraan yang lebih cepat membutuhkan waktu yang lebih sedikit untuk menempuh jarak yang sama.",hint:"Untuk jarak yang sama, kendaraan yang lebih cepat butuh waktu lebih sedikit atau lebih banyak?"},
{n:5,type:"mcq",micro:"Kecepatan konsisten vs kecepatan sesaat",q:"Seekor kelinci berlari sangat cepat tetapi hanya sebentar, sedangkan seekor kura-kura berjalan sangat lambat tetapi terus-menerus tanpa berhenti. Dalam cerita klasik, siapa yang akhirnya memenangkan perlombaan jarak jauh?",options:["Kelinci, karena ia berlari jauh lebih cepat dari kura-kura","Kura-kura, karena ia terus bergerak meskipun lambat","Keduanya sama, karena tidak seorang pun tahu siapa yang lebih jauh"],answer:1,explain:"Bergerak terus-menerus meski lambat bisa mengungguli kecepatan tinggi yang terputus-putus, sebuah pelajaran klasik tentang konsistensi.",hint:"Siapa yang benar-benar terus bergerak sepanjang perlombaan, tanpa berhenti di tengah jalan?"},
{n:6,type:"mcq",micro:"Jarak jauh dalam waktu singkat menunjukkan kecepatan tinggi",q:"Sebuah pesawat terbang menempuh jarak yang sangat jauh dalam waktu yang relatif singkat. Apa yang ini tunjukkan tentang kecepatan pesawat?",options:["Pesawat memiliki kecepatan yang sangat rendah","Jarak tidak berhubungan dengan kecepatan pesawat","Pesawat memiliki kecepatan yang sangat tinggi"],answer:2,explain:"Menempuh jarak jauh dalam waktu singkat adalah ciri khas kecepatan yang sangat tinggi.",hint:"Untuk menempuh jarak yang sangat jauh dalam waktu yang singkat, apakah dibutuhkan kecepatan tinggi atau rendah?"},
{n:7,type:"mcq",micro:"Menyimpulkan kecepatan dari waktu tiba",q:"Dua mobil berangkat dari tempat yang sama pada waktu yang sama menuju arah yang sama. Mobil A tiba lebih dulu di tujuan yang sama. Apa yang bisa disimpulkan?",options:["Mobil A bergerak lebih cepat daripada mobil B","Mobil A menempuh jarak yang lebih pendek","Belum cukup informasi untuk menyimpulkan"],answer:0,explain:"Karena berangkat bersamaan dan menuju tujuan yang sama, tiba lebih dulu berarti bergerak lebih cepat.",hint:"Jika keduanya berangkat bersamaan dan menuju tempat yang sama, apa yang membuat salah satunya tiba lebih dulu?"},
{n:8,type:"mcq",micro:"Analogi konkret laju air",q:"Sebuah keran air mengalirkan air dengan deras (cepat), sedangkan keran lain mengalirkan air dengan pelan. Keran mana yang akan mengisi penuh ember yang sama lebih dulu?",options:["Keran yang mengalirkan air dengan pelan","Keran yang mengalirkan air dengan deras","Keduanya akan selesai bersamaan"],answer:1,explain:"Laju yang lebih tinggi (lebih deras) mengisi volume yang sama dalam waktu yang lebih singkat.",hint:"Keran mana yang mengalirkan lebih banyak air setiap detiknya?"},
{n:9,type:"mcq",micro:"Percepatan mengurangi waktu tempuh",q:"Ketika sebuah mobil melaju semakin cepat (dipercepat), apa yang terjadi pada waktu yang dibutuhkan untuk menempuh jarak tertentu?",options:["Waktu yang dibutuhkan menjadi lebih banyak","Waktu yang dibutuhkan tetap sama","Waktu yang dibutuhkan menjadi lebih sedikit"],answer:2,explain:"Semakin cepat suatu kendaraan bergerak, semakin sedikit waktu yang dibutuhkan untuk jarak yang sama.",hint:"Jika kamu bergerak lebih cepat, apakah kamu sampai tujuan lebih cepat atau lebih lambat?"},
{n:10,type:"mcq",micro:"Kecepatan lebih tinggi menempuh jarak lebih jauh",q:"Seorang anak mengendarai sepeda dengan santai (pelan), lalu mengayuh lebih kencang. Apa yang terjadi pada jarak yang bisa ditempuhnya dalam waktu yang sama?",options:["Jarak yang ditempuh menjadi lebih jauh","Jarak yang ditempuh menjadi lebih dekat","Jarak yang ditempuh tetap sama"],answer:0,explain:"Mengayuh lebih kencang (kecepatan lebih tinggi) memungkinkan menempuh jarak lebih jauh dalam waktu yang sama.",hint:"Jika kamu bergerak lebih cepat dalam waktu yang sama, apakah kamu bisa pergi lebih jauh atau tidak?"},
{n:11,type:"mcq",micro:"Berhenti mengurangi kecepatan rata-rata",q:"Bus antar kota biasanya berhenti di beberapa halte, sedangkan kereta ekspres berjalan tanpa berhenti menuju tujuan yang sama. Kendaraan mana yang kemungkinan besar tiba lebih dulu (dengan jarak sama)?",options:["Bus antar kota, karena ia bisa menaikkan penumpang di sepanjang jalan","Kereta ekspres, karena tidak ada waktu yang terbuang untuk berhenti","Keduanya sama cepat, karena tujuan akhirnya sama persis untuk keduanya"],answer:1,explain:"Waktu yang terbuang untuk berhenti mengurangi kecepatan rata-rata keseluruhan perjalanan.",hint:"Apakah berhenti di tengah perjalanan menambah atau mengurangi total waktu tempuh?"},
{n:12,type:"mcq",micro:"Dua informasi yang dibutuhkan untuk kecepatan",q:"Untuk menggambarkan seberapa cepat sesuatu bergerak, informasi apa yang perlu digabungkan?",options:["Hanya seberapa berat benda yang bergerak dan warna benda itu","Hanya seberapa jauh jarak yang ditempuh, tanpa memedulikan waktu","Seberapa jauh jarak yang ditempuh DAN berapa lama waktu yang dibutuhkan"],answer:2,explain:"Kecepatan selalu membandingkan jarak dengan waktu, sehingga keduanya dibutuhkan bersamaan.",hint:"Apakah mengetahui jaraknya saja, tanpa tahu berapa lama waktunya, sudah cukup untuk mengetahui kecepatan?"},
{n:13,type:"mcq",micro:"Kecepatan tetap membagi jarak merata",q:"Seorang pelari maraton berlari dengan kecepatan tetap sepanjang lomba, tanpa mempercepat atau memperlambat langkahnya. Apa yang terjadi pada jarak yang ditempuhnya setiap 10 menit?",options:["Jarak yang ditempuh setiap 10 menit selalu sama","Jarak yang ditempuh setiap 10 menit selalu berbeda-beda","Jarak yang ditempuh menjadi nol setelah beberapa saat"],answer:0,explain:"Kecepatan yang benar-benar tetap berarti jarak yang ditempuh pada setiap interval waktu yang sama juga sama.",hint:"Jika kecepatannya benar-benar tidak berubah, apakah jarak setiap 10 menit akan berbeda-beda?"},
{n:14,type:"mcq",micro:"Jarak lebih jauh dalam waktu sama berarti lebih cepat",q:"Dua sepeda motor menempuh jarak yang berbeda dalam waktu yang sama persis. Motor mana yang lebih cepat?",options:["Motor yang menempuh jarak lebih pendek","Motor yang menempuh jarak lebih jauh","Tidak bisa ditentukan tanpa informasi tambahan"],answer:1,explain:"Untuk waktu yang sama, menempuh jarak yang lebih jauh menunjukkan kecepatan yang lebih tinggi.",hint:"Dalam waktu yang sama, motor mana yang berhasil pergi lebih jauh?"},
{n:15,type:"mcq",micro:"Kecepatan sangat rendah butuh waktu sangat lama",q:"Sebuah siput bergerak sangat lambat. Berapa lama kira-kira waktu yang dibutuhkan siput untuk menempuh jarak yang jauh, dibandingkan seekor kucing yang berlari?",options:["Siput membutuhkan waktu yang lebih sedikit","Keduanya membutuhkan waktu yang sama","Siput membutuhkan waktu yang jauh lebih lama"],answer:2,explain:"Kecepatan yang jauh lebih rendah membutuhkan waktu yang jauh lebih lama untuk jarak yang sama.",hint:"Untuk jarak yang sama, hewan yang jauh lebih lambat butuh waktu lebih sedikit atau lebih banyak?"},
{n:16,type:"mcq",micro:"Melambat mengurangi jarak per satuan waktu",q:"Ketika sebuah mobil direm dan melambat, apa yang terjadi pada jarak yang bisa ditempuhnya dalam satu menit?",options:["Jarak yang ditempuh dalam satu menit menjadi lebih pendek","Jarak yang ditempuh dalam satu menit menjadi lebih jauh","Jarak yang ditempuh tidak terpengaruh oleh pengereman"],answer:0,explain:"Melambat berarti kecepatan menurun, sehingga jarak yang ditempuh dalam waktu yang sama menjadi lebih pendek.",hint:"Jika sebuah mobil bergerak lebih lambat, apakah ia menempuh jarak yang sama, lebih jauh, atau lebih pendek dalam satu menit?"},
{n:17,type:"mcq",micro:"Arus memengaruhi kecepatan terhadap tepi",q:"Sebuah perahu bergerak melawan arus sungai yang deras, sedangkan perahu lain bergerak searah dengan arus yang sama. Perahu mana yang kemungkinan bergerak lebih lambat terhadap tepi sungai?",options:["Perahu yang searah arus","Perahu yang melawan arus","Keduanya sama cepat geraknya"],answer:1,explain:"Arus yang berlawanan arah mengurangi kecepatan perahu terhadap tepi sungai, sementara arus yang searah menambahnya.",hint:"Apakah melawan arus air membuat perahu bergerak lebih cepat atau lebih lambat terhadap tepi sungai?"},
{n:18,type:"mcq",micro:"Membandingkan kecepatan dengan jarak dan waktu berbeda",q:"Untuk membandingkan kecepatan dua pelari yang menempuh jarak BERBEDA dalam waktu yang BERBEDA pula, apa yang perlu diperhatikan?",options:["Membandingkan jarak yang ditempuh saja, karena pelari yang lebih jauh dianggap lebih cepat tanpa melihat waktu","Membandingkan waktu yang dibutuhkan saja, karena pelari yang lebih lama dianggap lebih lambat tanpa melihat jarak","Membandingkan seberapa jauh jarak yang ditempuh dibagi dengan waktu yang dibutuhkan masing-masing"],answer:2,explain:"Ketika jarak dan waktu keduanya berbeda, kecepatan (jarak dibagi waktu) adalah cara adil untuk membandingkan.",hint:"Jika jarak dan waktu keduanya berbeda, apakah membandingkan hanya salah satunya saja sudah cukup adil?"},
{n:19,type:"mcq",micro:"Jarak pulang-pergi",q:"Sebuah drone terbang dari titik A ke titik B, lalu kembali lagi ke titik A, menempuh rute yang sama persis. Apa yang bisa dikatakan tentang total jarak yang ditempuh dibandingkan jarak dari A ke B saja?",options:["Total jarak yang ditempuh dua kali lipat dari jarak A ke B","Total jarak yang ditempuh sama dengan jarak A ke B saja","Total jarak yang ditempuh menjadi nol karena kembali ke titik awal"],answer:0,explain:"Menempuh rute yang sama dua kali (pergi dan pulang) menggandakan total jarak yang ditempuh, meskipun posisi akhirnya kembali ke awal.",hint:"Apakah 'jarak yang ditempuh' sama dengan 'posisi akhir', atau berbeda?"},
{n:20,type:"mcq",micro:"Memeriksa klaim tentang kecepatan",q:"Seseorang berkata 'kecepatan hanya penting untuk kendaraan bermotor, tidak untuk hal lain.' Apakah pernyataan ini benar?",options:["Benar — kecepatan hanya penting untuk kendaraan bermotor, sedangkan manusia, hewan, dan air tidak punya kecepatan yang bisa diukur","Salah — kecepatan berlaku untuk apa pun yang bergerak, termasuk manusia berjalan, hewan berlari, air mengalir, dan lainnya","Benar — kecepatan hanya berlaku untuk benda yang punya mesin, sehingga makhluk hidup tidak pernah dinilai dengan ukuran kecepatan"],answer:1,explain:"Konsep kecepatan (jarak dibagi waktu) berlaku untuk semua benda yang bergerak, bukan hanya kendaraan bermotor.",hint:"Bisakah manusia yang berjalan kaki atau air yang mengalir juga memiliki kecepatan?"},
{n:21,type:"mcq",micro:"Membaca pola pada tabel jarak-waktu",q:"Sebuah tabel menunjukkan jarak tempuh mobil setiap jam: Jam 1: 60 km, Jam 2: 120 km, Jam 3: 180 km. Berapa jarak tambahan yang ditempuh setiap jam?",options:["120 km setiap jam","180 km setiap jam","60 km setiap jam"],answer:2,explain:"Selisih antar setiap jam adalah 60 km (120−60=60, 180−120=60), menunjukkan kecepatan tetap 60 km/jam.",hint:"Hitung selisih jarak antara jam yang berurutan."},
{n:22,type:"mcq",micro:"Kemiringan grafik menunjukkan kecepatan",q:"Pada grafik jarak-waktu, garis yang lebih curam (naik lebih tajam) menunjukkan apa dibandingkan garis yang lebih landai?",options:["Kecepatan yang lebih tinggi","Kecepatan yang lebih rendah","Jarak yang lebih pendek"],answer:0,explain:"Garis yang lebih curam pada grafik jarak-waktu berarti jarak bertambah lebih cepat, yaitu kecepatan lebih tinggi.",hint:"Apakah garis yang naik lebih tajam berarti jarak bertambah lebih cepat atau lebih lambat?"},
{n:23,type:"mcq",micro:"Garis mendatar berarti berhenti",q:"Sebuah grafik jarak-waktu menunjukkan garis lurus mendatar (tidak naik) selama beberapa menit. Apa yang ditunjukkan oleh bagian grafik ini?",options:["Objek tersebut bergerak makin cepat dengan stabil","Objek tersebut sedang berhenti (tidak bergerak)","Objek tersebut bergerak mundur dengan laju tetap"],answer:1,explain:"Garis mendatar berarti jarak tidak bertambah sama sekali, yang berarti objek sedang diam.",hint:"Jika jarak tidak bertambah sama sekali selama beberapa menit, apakah objek tersebut sedang bergerak atau diam?"},
{n:24,type:"mcq",micro:"Sumbu pada grafik jarak-waktu",q:"Pada grafik jarak-waktu, sumbu vertikal (y) biasanya menunjukkan apa?",options:["Waktu yang telah berlalu","Kecepatan kendaraan","Jarak yang telah ditempuh"],answer:2,explain:"Pada grafik jarak-waktu, sumbu vertikal menunjukkan jarak, sedangkan sumbu horizontal menunjukkan waktu.",hint:"Antara jarak dan waktu, mana yang biasanya digambar naik-turun (vertikal), dan mana yang bergerak dari kiri ke kanan (horizontal)?"},
{n:25,type:"order",micro:"Mengurutkan langkah membaca kecepatan dari grafik",q:"Urutkan langkah-langkah berikut untuk membaca kecepatan dari sebuah grafik jarak-waktu yang berupa garis lurus.",items:["Bagi jarak tersebut dengan waktu yang bersesuaian untuk mendapatkan kecepatan","Pilih dua titik pada garis grafik tersebut","Baca perubahan jarak dan perubahan waktu di antara kedua titik tersebut"],answer:[1,2,0],explain:"Pilih dua titik, baca perubahan jarak dan waktu di antaranya, baru bagi untuk mendapatkan kecepatan.",hint:"Bisakah kamu membagi jarak dan waktu sebelum memilih dua titik pada grafik?"},
{n:26,type:"mcq",micro:"Membaca pola pada tabel jarak-waktu",q:"Sebuah tabel menunjukkan: Waktu 0 jam, Jarak 0 km; Waktu 1 jam, Jarak 50 km; Waktu 2 jam, Jarak 100 km. Pola apa yang terlihat?",options:["Jarak bertambah 50 km setiap 1 jam, menunjukkan kecepatan tetap 50 km/jam","Jarak bertambah 100 km setiap 1 jam, menunjukkan kecepatan tetap 100 km/jam","Jarak bertambah makin kecil setiap jam, menunjukkan kecepatan makin lambat"],answer:0,explain:"Kenaikan jarak yang merata (50 km setiap jam) menunjukkan kecepatan tetap 50 km/jam.",hint:"Apakah kenaikan jarak setiap jam pada tabel ini sama, atau berbeda-beda?"},
{n:27,type:"mcq",micro:"Membandingkan kemiringan dua garis grafik",q:"Pada grafik jarak-waktu untuk dua kendaraan, Kendaraan A memiliki garis yang lebih curam daripada Kendaraan B. Apa artinya?",options:["Kendaraan B bergerak lebih cepat daripada Kendaraan A","Kendaraan A bergerak lebih cepat daripada Kendaraan B","Kedua kendaraan bergerak dengan kecepatan yang sama persis"],answer:1,explain:"Garis yang lebih curam pada grafik jarak-waktu menunjukkan kecepatan yang lebih tinggi.",hint:"Kemiringan garis yang lebih curam pada grafik jarak-waktu selalu berhubungan dengan apa?"},
{n:28,type:"mcq",micro:"Diagram dua kendaraan saling mendekat",q:"Sebuah diagram menunjukkan dua mobil bergerak saling mendekat dari dua kota yang berbeda menuju satu titik pertemuan di tengah. Apa yang akan terjadi seiring berjalannya waktu?",options:["Jarak di antara keduanya akan semakin besar hingga akhirnya terpisah jauh","Jarak di antara keduanya akan tetap sama sepanjang perjalanan mereka","Jarak di antara keduanya akan semakin berkurang hingga akhirnya bertemu"],answer:2,explain:"Bergerak saling mendekat berarti jarak di antara keduanya terus berkurang seiring waktu.",hint:"Jika kedua mobil bergerak menuju satu sama lain, apakah jarak di antara mereka bertambah atau berkurang?"},
{n:29,type:"mcq",micro:"Garis menurun pada grafik jarak-waktu",q:"Pada grafik jarak-waktu, sebuah garis yang menurun (turun) menunjukkan apa?",options:["Objek tersebut sedang bergerak kembali mendekati titik awal","Objek tersebut bergerak menjauh dari titik awal","Objek tersebut berhenti pada jarak tertentu dari titik awal"],answer:0,explain:"Garis yang menurun berarti jarak dari titik awal berkurang, menunjukkan objek bergerak kembali mendekat.",hint:"Jika jarak dari titik awal semakin berkurang seiring waktu, ke arah mana objek tersebut bergerak?"},
{n:30,type:"classify",micro:"Membaca bentuk grafik jarak-waktu",q:"Kelompokkan setiap bagian grafik jarak-waktu berikut berdasarkan artinya.",items:["Garis lurus naik dengan kemiringan tetap","Garis mendatar (tidak naik atau turun)","Garis lurus naik dengan kemiringan sangat curam"],groups:["Bergerak dengan kecepatan tetap","Sedang berhenti","Bergerak dengan kecepatan tinggi"],answer:{"Bergerak dengan kecepatan tetap":["Garis lurus naik dengan kemiringan tetap"],"Sedang berhenti":["Garis mendatar (tidak naik atau turun)"],"Bergerak dengan kecepatan tinggi":["Garis lurus naik dengan kemiringan sangat curam"]},explain:"Kemiringan garis pada grafik jarak-waktu langsung menunjukkan kecepatan: tetap, curam (tinggi), atau nol (berhenti) saat mendatar.",hint:"Perhatikan apakah garis naik, seberapa curam kenaikannya, atau apakah garis tersebut mendatar sama sekali."},
{n:31,type:"mcq",micro:"Kecepatan tidak tetap dari tabel tidak merata",q:"Sebuah tabel jarak-waktu menunjukkan hasil yang tidak bertambah secara merata (kadang naik banyak, kadang naik sedikit). Apa yang ini tunjukkan tentang kecepatan objek tersebut?",options:["Kecepatan objek tersebut tetap, tidak berubah","Kecepatan objek tersebut berubah-ubah, tidak tetap","Objek tersebut berhenti pada saat-saat tertentu dalam tabel"],answer:1,explain:"Kenaikan jarak yang tidak merata pada setiap interval waktu menunjukkan kecepatan yang berubah-ubah.",hint:"Jika kenaikan jarak berbeda-beda setiap interval waktu, apakah kecepatannya tetap atau berubah-ubah?"},
{n:32,type:"mcq",micro:"Garis sejajar berarti kecepatan sama",q:"Pada grafik jarak-waktu, dua garis yang sejajar (memiliki kemiringan sama) menunjukkan apa tentang kedua kendaraan tersebut?",options:["Kedua kendaraan menempuh jarak yang sama persis","Kedua kendaraan berangkat pada waktu yang sama","Kedua kendaraan bergerak dengan kecepatan yang sama"],answer:2,explain:"Kemiringan yang sama pada grafik jarak-waktu berarti kecepatan yang sama, meskipun posisi awal bisa berbeda.",hint:"Apakah kemiringan garis yang sama selalu berarti kecepatan yang sama, terlepas dari titik awalnya?"},
{n:33,type:"mcq",micro:"Informasi yang dibutuhkan untuk menyusul",q:"Sebuah diagram menunjukkan mobil A berangkat dari titik 0 km, dan mobil B berangkat dari titik 20 km pada saat yang sama, keduanya bergerak ke arah yang sama dengan kecepatan berbeda. Informasi apa yang dibutuhkan untuk mengetahui kapan mobil A menyusul mobil B?",options:["Kecepatan masing-masing mobil dan jarak awal 20 km di antara keduanya","Hanya kecepatan mobil A, karena mobil B diam di tempatnya","Hanya jarak awal 20 km, karena kecepatan kedua mobil tidak memengaruhi pertemuan"],answer:0,explain:"Mengetahui kapan satu kendaraan menyusul yang lain membutuhkan kecepatan masing-masing dan jarak awal di antara mereka.",hint:"Apakah mengetahui jarak awal saja, tanpa tahu kecepatan masing-masing mobil, sudah cukup untuk menentukan kapan mobil A menyusul?"},
{n:34,type:"mcq",micro:"Waktu per kilometer yang bertambah",q:"Pada tabel kecepatan pelari maraton setiap kilometer, waktu yang dicatat semakin lama untuk setiap kilometer berikutnya menjelang akhir lomba. Apa yang ini tunjukkan?",options:["Pelari tersebut mulai mempercepat larinya","Pelari tersebut mulai melambat menjelang akhir lomba","Jarak setiap kilometer menjadi lebih panjang"],answer:1,explain:"Membutuhkan waktu lebih lama untuk jarak yang sama (1 km) menunjukkan pelari tersebut melambat.",hint:"Jika waktu yang dibutuhkan untuk jarak yang sama (1 km) semakin lama, apakah pelari tersebut mempercepat atau melambat?"},
{n:35,type:"mcq",micro:"Grafik yang tiba-tiba mendatar",q:"Sebuah grafik menunjukkan jarak tempuh kereta yang naik dengan kemiringan tetap selama 3 jam, lalu tiba-tiba menjadi mendatar. Apa yang paling mungkin terjadi pada kereta tersebut?",options:["Kereta tiba-tiba bergerak jauh lebih cepat","Kereta bergerak mundur ke stasiun awal","Kereta berhenti setelah 3 jam perjalanan"],answer:2,explain:"Garis yang mendadak mendatar setelah sebelumnya naik menunjukkan kendaraan tersebut berhenti bergerak.",hint:"Apa arti garis mendatar pada grafik jarak-waktu?"},
{n:36,type:"mcq",micro:"Titik pertemuan dua kendaraan dengan kecepatan sama",q:"Melanjutkan diagram dua mobil yang saling mendekat, jika kedua mobil memiliki kecepatan yang sama persis, di mana kira-kira mereka akan bertemu?",options:["Tepat di titik tengah antara kedua kota","Lebih dekat ke kota mobil yang lebih cepat","Mereka tidak akan pernah bertemu"],answer:0,explain:"Jika kecepatan keduanya sama, masing-masing menempuh jarak yang sama sebelum bertemu, sehingga bertemu di titik tengah.",hint:"Jika kedua mobil menempuh jarak yang sama sebelum bertemu (karena kecepatannya sama), di mana titik pertemuannya?"},
{n:37,type:"mcq",micro:"Membaca grafik kecepatan-waktu",q:"Pada grafik kecepatan-waktu (bukan jarak-waktu), garis mendatar pada ketinggian tertentu menunjukkan apa?",options:["Kecepatan yang terus bertambah selama periode tersebut","Kecepatan yang tetap (konstan) selama periode tersebut","Objek berhenti dan tidak bergerak selama periode tersebut"],answer:1,explain:"Pada grafik kecepatan-waktu, garis mendatar pada suatu ketinggian menunjukkan kecepatan yang tidak berubah (tetap) pada nilai tersebut.",hint:"Ingat bahwa ini adalah grafik KECEPATAN-waktu, bukan jarak-waktu — apa yang ditunjukkan sumbu vertikalnya?"},
{n:38,type:"mcq",micro:"Pola umum kemiringan dan kecepatan",q:"Melihat beberapa grafik jarak-waktu dengan garis lurus yang kemiringannya berbeda-beda, pola apa yang selalu berlaku?",options:["Kemiringan garis tidak ada hubungannya dengan kecepatan","Setiap grafik jarak-waktu memiliki arti yang benar-benar berbeda tanpa pola umum","Semakin curam kemiringan garis, semakin tinggi kecepatan yang ditunjukkan"],answer:2,explain:"Hubungan antara kemiringan garis dan kecepatan berlaku secara konsisten di semua grafik jarak-waktu.",hint:"Apakah hubungan antara kemiringan dan kecepatan berlaku sama di SETIAP grafik jarak-waktu yang kamu lihat?"},
{n:39,type:"mcq",micro:"Menghitung dari informasi tabel/papan informasi",q:"Sebuah tabel menunjukkan waktu tempuh kereta dari kota A ke kota B adalah 2 jam, dan jaraknya 180 km, seperti tertulis pada papan informasi stasiun. Informasi apa yang bisa dihitung dari data ini?",options:["Kecepatan rata-rata kereta tersebut","Warna kereta tersebut","Jumlah penumpang di kereta tersebut"],answer:0,explain:"Dengan jarak dan waktu diketahui, kecepatan rata-rata bisa dihitung dengan membagi jarak dengan waktu.",hint:"Dengan jarak dan waktu sudah diketahui, besaran apa yang bisa dihitung dari keduanya?"},
{n:40,type:"mcq",micro:"Strategi membandingkan dua grafik",q:"Untuk membandingkan dua grafik jarak-waktu dari dua kendaraan yang berbeda, pendekatan apa yang membantu menentukan mana yang lebih cepat?",options:["Membandingkan warna garis pada grafik","Membandingkan kemiringan (seberapa curam) masing-masing garis","Hanya melihat garis mana yang digambar lebih panjang"],answer:1,explain:"Kemiringan garis pada grafik jarak-waktu adalah indikator langsung dari kecepatan.",hint:"Fitur grafik mana yang berhubungan langsung dengan kecepatan — kemiringannya, atau warnanya?"},
{n:41,type:"mcq",micro:"Menghitung kecepatan rata-rata",q:"Sebuah mobil menempuh jarak 150 km dalam waktu 3 jam. Berapa kecepatan rata-ratanya?",options:["450 km/jam","3 km/jam","50 km/jam"],answer:2,explain:"Kecepatan = jarak ÷ waktu = 150 ÷ 3 = 50 km/jam.",hint:"Bagi jarak dengan waktu untuk mendapatkan kecepatan."},
{n:42,type:"mcq",micro:"Menghitung kecepatan rata-rata",q:"Sebuah sepeda motor menempuh jarak 80 km dalam waktu 2 jam. Berapa kecepatan rata-ratanya?",options:["40 km/jam","160 km/jam","2 km/jam"],answer:0,explain:"Kecepatan = 80 ÷ 2 = 40 km/jam.",hint:"Bagi jarak dengan waktu untuk mendapatkan kecepatan."},
{n:43,type:"mcq",micro:"Menghitung jarak dari kecepatan dan waktu",q:"Sebuah mobil bergerak dengan kecepatan tetap 60 km/jam selama 4 jam. Berapa jarak yang ditempuhnya?",options:["64 km","240 km","15 km"],answer:1,explain:"Jarak = kecepatan × waktu = 60 × 4 = 240 km.",hint:"Kalikan kecepatan dengan waktu untuk mendapatkan jarak."},
{n:44,type:"mcq",micro:"Menghitung jarak dari kecepatan dan waktu",q:"Sebuah kereta bergerak dengan kecepatan tetap 90 km/jam selama 3 jam. Berapa jarak yang ditempuhnya?",options:["93 km","30 km","270 km"],answer:2,explain:"Jarak = 90 × 3 = 270 km.",hint:"Kalikan kecepatan dengan waktu untuk mendapatkan jarak."},
{n:45,type:"mcq",micro:"Menghitung waktu dari jarak dan kecepatan",q:"Sebuah pesawat perlu menempuh jarak 900 km dengan kecepatan 300 km/jam. Berapa lama waktu yang dibutuhkan?",options:["3 jam","600 jam","1200 jam"],answer:0,explain:"Waktu = jarak ÷ kecepatan = 900 ÷ 300 = 3 jam.",hint:"Bagi jarak dengan kecepatan untuk mendapatkan waktu."},
{n:46,type:"mcq",micro:"Menghitung waktu dari jarak dan kecepatan",q:"Sebuah bus perlu menempuh jarak 210 km dengan kecepatan 70 km/jam. Berapa lama waktu yang dibutuhkan?",options:["140 jam","3 jam","280 jam"],answer:1,explain:"Waktu = 210 ÷ 70 = 3 jam.",hint:"Bagi jarak dengan kecepatan untuk mendapatkan waktu."},
{n:47,type:"mcq",micro:"Konversi km/jam ke m/detik",q:"Ubahlah kecepatan 72 km/jam menjadi satuan m/detik.",options:["72 m/detik","259200 m/detik","20 m/detik"],answer:2,explain:"72 km/jam = 72×1000 meter ÷ 3600 detik = 72000÷3600 = 20 m/detik.",hint:"Ubah km menjadi meter (kalikan 1000), lalu bagi dengan jumlah detik dalam satu jam (3600)."},
{n:48,type:"order",micro:"Mengurutkan langkah konversi satuan kecepatan",q:"Urutkan langkah-langkah berikut untuk mengubah kecepatan 36 km/jam menjadi m/detik.",items:["Hasil akhirnya adalah 10 m/detik","Kalikan 36 km dengan 1000 untuk mendapatkan 36000 meter","Bagi 36000 meter dengan 3600 detik (jumlah detik dalam 1 jam)"],answer:[1,2,0],explain:"Ubah km menjadi meter terlebih dahulu, lalu bagi dengan jumlah detik dalam satu jam untuk mendapatkan hasil akhir.",hint:"Bisakah kamu membagi dengan 3600 detik sebelum mengubah km menjadi meter?"},
{n:49,type:"mcq",micro:"Konversi m/detik ke km/jam",q:"Ubahlah kecepatan 15 m/detik menjadi satuan km/jam.",options:["54 km/jam","15 km/jam","150 km/jam"],answer:0,explain:"15 m/detik × 3600 detik ÷ 1000 = 54000÷1000 = 54 km/jam.",hint:"Kalikan dengan jumlah detik dalam satu jam (3600), lalu ubah meter menjadi km (bagi 1000)."},
{n:50,type:"mcq",micro:"Kecepatan rata-rata dari dua tahap perjalanan",q:"Sebuah mobil menempuh 120 km dalam 2 jam pertama, lalu 60 km dalam 1 jam berikutnya. Berapa kecepatan rata-rata untuk seluruh perjalanan?",options:["90 km/jam","60 km/jam","180 km/jam"],answer:1,explain:"Total jarak = 120+60=180 km, total waktu = 2+1=3 jam, kecepatan rata-rata = 180÷3=60 km/jam.",hint:"Jumlahkan seluruh jarak dan seluruh waktu terlebih dahulu, baru bagi keduanya — jangan merata-ratakan kecepatan setiap tahap secara langsung."},
{n:51,type:"mcq",micro:"Kecepatan relatif saling mendekat",q:"Dua mobil bergerak saling mendekat dari dua arah berlawanan, satu dengan kecepatan 50 km/jam dan lainnya 70 km/jam. Berapa kecepatan mereka saling mendekat (kecepatan relatif)?",options:["20 km/jam","3500 km/jam","120 km/jam"],answer:2,explain:"Untuk gerakan saling berlawanan arah, kecepatan relatif adalah jumlah kedua kecepatan: 50+70=120 km/jam.",hint:"Untuk dua benda yang bergerak berlawanan arah, apakah kecepatan relatifnya berupa jumlah atau selisih?"},
{n:52,type:"mcq",micro:"Kecepatan relatif saat menyusul",q:"Dua mobil bergerak searah, satu dengan kecepatan 80 km/jam mengejar mobil lain yang bergerak 60 km/jam. Berapa kecepatan mobil pertama mendekati mobil kedua (kecepatan relatif)?",options:["20 km/jam","140 km/jam","4800 km/jam"],answer:0,explain:"Untuk gerakan searah, kecepatan relatif adalah selisih kedua kecepatan: 80−60=20 km/jam.",hint:"Untuk dua benda yang bergerak searah, apakah kecepatan relatifnya berupa jumlah atau selisih?"},
{n:53,type:"mcq",micro:"Kecepatan perahu searah arus",q:"Sebuah perahu bergerak dengan kecepatan 15 km/jam di air tenang. Jika arus sungai mengalir searah dengan perahu pada kecepatan 3 km/jam, berapa kecepatan perahu terhadap tepi sungai?",options:["12 km/jam","18 km/jam","45 km/jam"],answer:1,explain:"Arus yang searah menambah kecepatan perahu: 15+3=18 km/jam.",hint:"Apakah arus yang searah dengan gerakan perahu menambah atau mengurangi kecepatannya terhadap tepi sungai?"},
{n:54,type:"mcq",micro:"Kecepatan perahu melawan arus",q:"Sebuah perahu bergerak dengan kecepatan 15 km/jam di air tenang, melawan arus sungai yang mengalir pada kecepatan 3 km/jam. Berapa kecepatan perahu terhadap tepi sungai?",options:["18 km/jam","5 km/jam","12 km/jam"],answer:2,explain:"Arus yang berlawanan arah mengurangi kecepatan perahu: 15−3=12 km/jam.",hint:"Apakah arus yang melawan gerakan perahu menambah atau mengurangi kecepatannya terhadap tepi sungai?"},
{n:55,type:"mcq",micro:"Menghitung kecepatan dalam m/detik",q:"Sebuah pelari menempuh 400 meter dalam waktu 50 detik. Berapa kecepatan rata-ratanya dalam m/detik?",options:["8 m/detik","20000 m/detik","0.125 m/detik"],answer:0,explain:"Kecepatan = 400 ÷ 50 = 8 m/detik.",hint:"Bagi jarak (dalam meter) dengan waktu (dalam detik)."},
{n:56,type:"classify",micro:"Mencocokkan rumus dengan hasilnya",q:"Kelompokkan setiap rumus berikut sesuai dengan apa yang dihitungnya.",items:["Jarak dibagi waktu","Kecepatan dikali waktu","Jarak dibagi kecepatan"],groups:["Menghitung kecepatan","Menghitung jarak","Menghitung waktu"],answer:{"Menghitung kecepatan":["Jarak dibagi waktu"],"Menghitung jarak":["Kecepatan dikali waktu"],"Menghitung waktu":["Jarak dibagi kecepatan"]},explain:"Ketiga rumus ini adalah tiga bentuk berbeda dari hubungan yang sama antara kecepatan, jarak, dan waktu.",hint:"Ingat hubungan dasar: kecepatan = jarak ÷ waktu, lalu susun ulang untuk mencari jarak atau waktu."},
{n:57,type:"mcq",micro:"Jarak akhir dari dua kereta berlawanan arah",q:"Dua kereta berangkat dari stasiun yang sama pada waktu yang sama, menuju arah berlawanan, dengan kecepatan 80 km/jam dan 100 km/jam. Berapa jarak di antara keduanya setelah 2 jam?",options:["40 km","360 km","180 km"],answer:1,explain:"Kecepatan relatif menjauh = 80+100=180 km/jam, dikalikan 2 jam = 360 km.",hint:"Hitung dulu kecepatan relatif keduanya menjauh, baru kalikan dengan waktu 2 jam."},
{n:58,type:"mcq",micro:"Efek melipatgandakan kecepatan pada waktu",q:"Sebuah mobil membutuhkan waktu 5 jam untuk menempuh 300 km. Jika kecepatannya ditingkatkan menjadi dua kali lipat, berapa lama waktu yang dibutuhkan untuk jarak yang sama?",options:["10 jam","1.25 jam","2.5 jam"],answer:2,explain:"Kecepatan awal=300÷5=60 km/jam, dua kali lipat=120 km/jam, waktu baru=300÷120=2,5 jam.",hint:"Hitung dulu kecepatan awalnya, lalu gandakan, baru hitung ulang waktunya."},
{n:59,type:"mcq",micro:"Konversi menit ke jam dalam perhitungan kecepatan",q:"Sebuah kendaraan menempuh 50 km dalam 30 menit. Berapa kecepatan rata-ratanya dalam km/jam?",options:["100 km/jam","25 km/jam","1500 km/jam"],answer:0,explain:"30 menit = 0,5 jam, kecepatan = 50 ÷ 0,5 = 100 km/jam.",hint:"Ubah dulu 30 menit menjadi satuan jam (0,5 jam) sebelum membagi."},
{n:60,type:"mcq",micro:"Memilih rumus yang tepat untuk waktu",q:"Untuk menghitung waktu yang dibutuhkan jika jarak dan kecepatan sudah diketahui, rumus mana yang digunakan?",options:["waktu = jarak × kecepatan","waktu = jarak ÷ kecepatan","waktu = kecepatan ÷ jarak"],answer:1,explain:"Waktu dihitung dengan membagi jarak dengan kecepatan, hasil penyusunan ulang dari rumus dasar kecepatan=jarak÷waktu.",hint:"Susun ulang rumus dasar kecepatan=jarak÷waktu untuk mengisolasi waktu."},
{n:61,type:"mcq",micro:"Kegunaan kecepatan rata-rata",q:"Mengapa mengetahui kecepatan rata-rata suatu perjalanan berguna, meskipun kecepatan sebenarnya berubah-ubah sepanjang perjalanan (kadang cepat, kadang lambat)?",options:["Karena kecepatan rata-rata menunjukkan kecepatan tepat di setiap momen perjalanan, sehingga rencana waktu tempuh akurat sampai satuan menit","Karena kecepatan rata-rata tidak berguna bila kecepatan sebenarnya berubah-ubah, sehingga perjalanan tak bisa direncanakan lewat angka rata-rata","Karena kecepatan rata-rata memberi perkiraan keseluruhan yang berguna untuk merencanakan waktu tempuh, meskipun tidak menggambarkan setiap momen secara persis"],answer:2,explain:"Kecepatan rata-rata adalah ringkasan praktis yang berguna untuk perencanaan, meskipun bukan gambaran setiap momen.",hint:"Apakah mengetahui perkiraan keseluruhan tetap berguna, walaupun bukan gambaran setiap detik perjalanan?"},
{n:62,type:"open",micro:"Analisis kesalahan",q:"Seorang siswa menghitung kecepatan mobil yang menempuh 150 km dalam 3 jam dengan menulis: kecepatan = 3 ÷ 150 = 0,02 km/jam. Temukan kesalahannya dan jelaskan cara yang benar.",explain:"Membalik urutan pembagian (waktu÷jarak, bukan jarak÷waktu) adalah kesalahan umum dalam menghitung kecepatan.",hint:"Apakah rumus kecepatan seharusnya jarak dibagi waktu, atau waktu dibagi jarak?",sample:"Siswa tersebut membalik pembagian — rumus kecepatan yang benar adalah jarak dibagi waktu, bukan waktu dibagi jarak: kecepatan = 150 ÷ 3 = 50 km/jam, bukan 0,02 km/jam yang jelas terlalu kecil untuk sebuah mobil."},
{n:63,type:"open",micro:"Memeriksa hasil perhitungan waktu",q:"Setelah menghitung waktu tempuh sebagai 4 jam untuk perjalanan 240 km dengan kecepatan 60 km/jam, bagaimana cara memeriksa apakah jawaban ini benar?",explain:"Mengalikan kembali kecepatan dengan waktu hasil perhitungan adalah cara memverifikasi jawaban.",hint:"Apakah mengalikan kembali kecepatan dengan waktu yang dihitung akan menghasilkan jarak asli jika jawabannya benar?",sample:"Kalikan kembali kecepatan dengan waktu yang dihitung: 60 km/jam × 4 jam = 240 km, yang cocok dengan jarak asal, sehingga mengonfirmasi jawaban 4 jam sudah benar."},
{n:64,type:"mcq",micro:"Mengapa estimasi navigasi berubah-ubah",q:"Sebuah aplikasi navigasi menampilkan estimasi waktu tiba berdasarkan kecepatan rata-rata di jalan tersebut. Mengapa estimasi ini bisa berubah-ubah selama perjalanan berlangsung?",options:["Karena kecepatan sebenarnya di jalan bisa berubah (macet, lampu merah, jalan lengang), sehingga aplikasi terus memperbarui perkiraan berdasarkan kondisi terkini","Karena kecepatan di jalan tetap, sehingga aplikasi hanya perlu menghitung satu kali di awal perjalanan dan estimasinya tidak pernah berubah","Karena pengguna tidak boleh melihat perubahan estimasi, jadi aplikasi menampilkan satu angka tetap yang tidak mengikuti kondisi jalan terkini"],answer:0,explain:"Kecepatan sebenarnya yang berubah-ubah di lapangan adalah alasan nyata mengapa estimasi navigasi terus diperbarui.",hint:"Apakah kondisi jalan seperti macet bisa mengubah kecepatan sebenarnya, sehingga estimasi perlu diperbarui?"},
{n:65,type:"open",micro:"Penalaran dunia nyata (penerbangan)",q:"Mengapa pilot pesawat perlu memperhitungkan kecepatan angin (apakah searah atau berlawanan dengan arah terbang) saat menghitung estimasi waktu penerbangan?",explain:"Ini adalah penerapan nyata dari konsep kecepatan relatif pada penerbangan, mirip dengan perahu melawan/searah arus.",hint:"Mirip dengan perahu melawan atau searah arus sungai, apakah angin bisa memengaruhi kecepatan pesawat terhadap daratan?",sample:"Angin yang searah dengan penerbangan akan menambah kecepatan pesawat terhadap daratan (mempercepat perjalanan), sedangkan angin yang berlawanan arah akan menguranginya (memperlambat perjalanan), sehingga mengabaikan faktor angin bisa membuat estimasi waktu penerbangan menjadi tidak akurat."},
{n:66,type:"mcq",micro:"Efisiensi satu rumus untuk banyak situasi",q:"Mengapa lebih efisien menggunakan rumus kecepatan = jarak ÷ waktu untuk BANYAK situasi berbeda (mobil, pelari, pesawat), dibandingkan mencari cara baru setiap kali?",options:["Karena setiap kendaraan membutuhkan rumus sendiri, sehingga rumus yang sama tidak boleh dipakai untuk mobil, pelari, dan pesawat","Karena hubungan antara jarak, waktu, dan kecepatan berlaku secara konsisten untuk semua benda yang bergerak, apa pun jenisnya","Karena rumus kecepatan hanya berlaku untuk mobil, sedangkan pelari dan pesawat harus dihitung dengan cara yang sama sekali berbeda"],answer:1,explain:"Satu rumus yang konsisten berlaku untuk semua benda yang bergerak, menjadikannya sangat efisien digunakan berulang kali.",hint:"Apakah rumus kecepatan yang sama bisa dipakai untuk mobil, pelari, DAN pesawat sekaligus?"},
{n:67,type:"open",micro:"Menyelidiki perbedaan hasil",q:"Dua siswa menghitung kecepatan rata-rata mobil yang menempuh 240 km dalam 4 jam dan mendapatkan hasil 60 km/jam dan 6 km/jam. Buatlah rencana langkah demi langkah untuk menemukan jawaban yang benar.",explain:"Menghitung ulang dengan teliti menggunakan rumus yang benar adalah cara paling andal untuk menemukan jawaban yang tepat.",hint:"Apakah menghitung ulang 240÷4 dengan teliti akan menunjukkan jawaban mana yang benar?",sample:"Hitung ulang dengan teliti: kecepatan = jarak ÷ waktu = 240 ÷ 4 = 60 km/jam, ini mengonfirmasi 60 km/jam sebagai jawaban yang benar; siswa yang mendapat 6 km/jam kemungkinan salah menghitung pembagian (240 dibagi 4 seharusnya 60, bukan 6)."},
{n:68,type:"mcq",micro:"Waktu istirahat dalam estimasi perjalanan",q:"Mengapa penting bagi pengemudi truk pengiriman untuk memperhitungkan waktu istirahat dalam estimasi total waktu perjalanan, bukan hanya jarak dibagi kecepatan saja?",options:["Karena waktu istirahat tidak memengaruhi waktu perjalanan, sehingga estimasi jarak dibagi kecepatan sudah cukup tepat untuk menghitung total waktu tiba","Karena waktu istirahat hanya penting bagi pengemudi yang lelah, sedangkan perusahaan tidak perlu memasukkannya dalam jadwal pengiriman barang","Karena waktu istirahat menambah total waktu perjalanan sebenarnya, sehingga estimasi yang hanya menghitung jarak dibagi kecepatan bergerak akan meleset dari kenyataan"],answer:2,explain:"Waktu istirahat adalah waktu tambahan nyata yang harus dihitung di luar rumus dasar jarak÷kecepatan.",hint:"Apakah waktu yang dihabiskan untuk istirahat termasuk dalam total waktu perjalanan yang sebenarnya?"},
{n:69,type:"open",micro:"Kecepatan relatif dan keselamatan berkendara",q:"Mengapa mengetahui kecepatan relatif antara dua kendaraan (misalnya saat satu mobil menyalip mobil lain) penting untuk keselamatan berkendara?",explain:"Kecepatan relatif secara langsung menentukan waktu dan jarak aman yang dibutuhkan untuk menyalip dengan selamat.",hint:"Apakah kesalahan memperkirakan kecepatan relatif bisa membuat proses menyalip memakan waktu lebih lama dari yang diharapkan?",sample:"Kecepatan relatif menentukan seberapa cepat jarak antara dua mobil berubah — jika kecepatan relatif terlalu tinggi atau perhitungan pengemudi salah, proses menyalip bisa memakan waktu lebih lama dari perkiraan dan meningkatkan risiko kecelakaan, terutama jika ada kendaraan dari arah berlawanan."},
{n:70,type:"mcq",micro:"Mengapa kecepatan relatif searah adalah selisih",q:"Mengapa kecepatan relatif dua kendaraan yang bergerak SEARAH selalu berupa SELISIH kecepatan keduanya, bukan jumlahnya?",options:["Karena jika keduanya bergerak ke arah yang sama, sebagian dari gerakan mereka 'saling meniadakan', sehingga yang tersisa hanyalah selisih kecepatan yang membuat salah satu mendekati atau menjauhi yang lain","Karena bila keduanya bergerak ke arah yang sama, kecepatan mereka saling menambah sehingga yang tersisa adalah jumlah kecepatan yang membuat salah satu cepat menyusul yang lain","Karena kecepatan relatif tidak bergantung pada arah gerak, sehingga selisih atau jumlah dipilih sembarang tanpa alasan khusus oleh para ahli fisika yang mempelajarinya"],answer:0,explain:"Gerakan searah membuat sebagian kecepatan 'saling meniadakan', sehingga hanya selisihnya yang menentukan seberapa cepat satu mendekati yang lain.",hint:"Jika kedua kendaraan bergerak ke arah yang persis sama, apakah kecepatan salah satunya 'ikut membantu' atau 'menghalangi' gerakan relatif terhadap yang lain?"},
{n:71,type:"open",micro:"Estimasi sebagai pemeriksa kesalahan",q:"Sebelum menghitung waktu tempuh 350 km dengan kecepatan 70 km/jam secara tepat, bagaimana perkiraan kasar bisa membantu memeriksa kesalahan?",explain:"Perkiraan kasar berfungsi sebagai pemeriksaan kewajaran terhadap hasil perhitungan yang tepat.",hint:"Apakah selisih besar antara perkiraan kasar dan hasil perhitungan tepat patut dicurigai?",sample:"Secara kasar, 350 dibagi 70 mendekati 5 (karena 70×5=350), jadi waktunya seharusnya sekitar 5 jam; jika hasil perhitungan tepatmu memberikan angka yang jauh berbeda seperti 50 jam, itu adalah tanda ada yang salah dalam perhitungan."},
{n:72,type:"mcq",micro:"Pola jarak bertambah pada kecepatan tetap",q:"Melihat beberapa contoh di mana kecepatan tetap sementara waktu bertambah, pola apa yang selalu terlihat pada jarak yang ditempuh?",options:["Jarak yang ditempuh kadang bertambah dan kadang berkurang tanpa pola","Jarak yang ditempuh selalu bertambah secara merata seiring bertambahnya waktu","Jarak yang ditempuh selalu tetap sama, tidak peduli berapa lama waktu berlalu"],answer:1,explain:"Kecepatan yang benar-benar tetap selalu menghasilkan pertambahan jarak yang merata seiring waktu, secara konsisten.",hint:"Jika kecepatan benar-benar tidak berubah, apakah pertambahan jaraknya konsisten di setiap contoh?"},
{n:73,type:"open",micro:"Refleksi pilihan strategi",q:"Ceritakan situasi nyata di mana perkiraan kasar waktu tempuh sudah cukup, dan situasi lain di mana kamu membutuhkan perhitungan waktu tempuh yang tepat menggunakan rumus.",explain:"Mengenali kapan presisi benar-benar penting, dan kapan perkiraan kasar sudah cukup, mencerminkan penilaian matematis yang matang.",hint:"Apakah perkiraan kasar berisiko dalam situasi yang membutuhkan koneksi tepat waktu, tetapi cukup untuk perjalanan santai sehari-hari?",sample:"Untuk hal seperti memperkirakan kapan harus berangkat agar tidak terlambat ke sekolah, perkiraan kasar sudah cukup; tetapi untuk hal seperti menjadwalkan penerbangan pesawat yang harus terhubung dengan penerbangan lain, perhitungan waktu tempuh yang tepat jauh lebih penting karena keterlambatan kecil bisa berakibat besar."},
{n:74,type:"mcq",micro:"Arti tanda perkiraan pada estimasi waktu",q:"Sebuah aplikasi menampilkan estimasi waktu tiba sebagai '≈45 menit.' Apa arti tanda '≈' pada estimasi tersebut?",options:["Waktu tiba sebenarnya persis 45 menit, karena tanda '≈' hanyalah hiasan dan tidak mengubah angka di aplikasi","Waktu tiba sebenarnya lebih lambat dari 45 menit, karena tanda '≈' berarti aplikasi menaksir terlalu cepat","Waktu tiba sebenarnya kemungkinan mendekati 45 menit, tetapi bisa sedikit berbeda tergantung kondisi jalan"],answer:2,explain:"Tanda '≈' menandakan sebuah perkiraan, bukan angka yang pasti dan tepat.",hint:"Apakah tanda '≈' biasanya menunjukkan angka yang pasti, atau sebuah perkiraan?"},
{n:75,type:"open",micro:"Bekerja teliti di bawah tekanan waktu",q:"Saat mengerjakan soal ujian dengan batas waktu yang melibatkan banyak perhitungan kecepatan, jarak, dan waktu, kebiasaan apa yang membantu menghindari kesalahan ceroboh?",explain:"Kebiasaan menuliskan rumus secara eksplisit sebelum menghitung membantu menjaga akurasi bahkan di bawah tekanan waktu.",hint:"Apakah menuliskan rumus terlebih dahulu, sebelum memasukkan angka, membantu menghindari kesalahan tertukar rumus?",sample:"Selalu menuliskan rumus yang akan digunakan terlebih dahulu (kecepatan=jarak/waktu, jarak=kecepatan×waktu, atau waktu=jarak/kecepatan) sebelum memasukkan angka, membantu menghindari kesalahan tertukar antara rumus yang seharusnya dipakai."},
{n:76,type:"mcq",micro:"Estimasi kedatangan pada aplikasi transportasi",q:"Mengapa aplikasi ojek online atau taksi online menampilkan estimasi waktu kedatangan berdasarkan kecepatan rata-rata di rute tersebut?",options:["Karena estimasi berbasis kecepatan rata-rata membantu pelanggan memperkirakan kapan kendaraan akan tiba, meskipun kecepatan sebenarnya bisa berubah-ubah karena kondisi jalan","Karena kecepatan rata-rata membuat waktu kedatangan tepat sampai satuan detik, sehingga pelanggan tidak perlu khawatir akan keterlambatan","Karena aplikasi tidak bisa memperkirakan kecepatan kendaraan, jadi waktu kedatangan ditentukan dengan menebak sesuai selera pengemudi saja"],answer:0,explain:"Estimasi berbasis kecepatan rata-rata memberikan perkiraan praktis yang berguna bagi pelanggan, meskipun bukan angka pasti.",hint:"Apakah pelanggan mendapat manfaat nyata dari mengetahui perkiraan waktu kedatangan, meskipun bukan angka yang pasti?"},
{n:77,type:"open",micro:"Menjelaskan hubungan tiga rumus",q:"Seorang teman bingung mengapa rumus jarak=kecepatan×waktu dan waktu=jarak÷kecepatan sebenarnya berasal dari rumus yang sama (kecepatan=jarak÷waktu). Apa yang akan kamu jelaskan, dan mengapa itu membantu?",explain:"Memahami bahwa ketiga rumus berasal dari satu hubungan dasar adalah pemahaman yang lebih dalam daripada sekadar menghafal tiga rumus terpisah.",hint:"Apakah ketiga rumus tersebut sebenarnya hanya susunan ulang dari satu hubungan dasar yang sama?",sample:"Saya akan menjelaskan bahwa ketiga rumus ini hanyalah cara menyusun ulang hubungan yang sama antara tiga besaran (kecepatan, jarak, waktu) — jika kamu tahu rumus dasarnya (kecepatan=jarak÷waktu), kamu bisa 'membalik' persamaan tersebut untuk mencari jarak atau waktu, sama seperti membalik persamaan aljabar biasa — memahami hubungan ini lebih baik daripada menghafal tiga rumus terpisah tanpa melihat keterkaitannya."},
{n:78,type:"mcq",micro:"Mengenali hasil kecepatan yang tidak mungkin",q:"Kamu menghitung kecepatan sebuah mobil dan mendapatkan hasil negatif, seperti -50 km/jam. Apa yang ini tunjukkan?",options:["Hasil itu wajar, karena mobil yang bergerak mundur otomatis memiliki kecepatan negatif dalam setiap konteks","Kemungkinan besar ada kesalahan perhitungan, karena kecepatan (besarnya) tidak bisa bernilai negatif dalam konteks ini","Hasil itu menunjukkan mobil bergerak sangat pelan, sehingga angka negatif adalah ukuran yang normal untuk kecepatan rendah"],answer:1,explain:"Besar kecepatan selalu bernilai positif atau nol dalam konteks ini; hasil negatif menandakan ada kesalahan dalam perhitungan.",hint:"Bisakah besar kecepatan suatu kendaraan bernilai negatif dalam kondisi normal?"},
{n:79,type:"open",micro:"Merancang sistem yang membantu",q:"Rancang cara sederhana bagi sebuah kelas untuk menghindari kesalahan umum saat menghitung kecepatan, jarak, atau waktu, seperti tertukar rumus yang digunakan.",explain:"Alat bantu visual seperti segitiga rumus, ditambah pemeriksaan satuan, adalah cara praktis mencegah kesalahan tertukar rumus.",hint:"Apakah alat bantu visual seperti segitiga rumus bisa membantu siswa mengingat rumus mana yang harus dipakai?",sample:"Mewajibkan siswa menuliskan segitiga rumus (jarak di atas, kecepatan dan waktu di bawah) sebagai alat bantu visual sebelum menghitung, dan selalu memeriksa apakah satuan (km/jam, m/detik) pada jawaban akhir masuk akal untuk situasi tersebut."},
{n:80,type:"mcq",micro:"Memeriksa keyakinan dari beberapa percobaan",q:"Kamu menghitung kecepatan rata-rata yang sama sebanyak tiga kali dan mendapatkan hasil 60, 60, dan 65 km/jam. Langkah apa yang paling masuk akal selanjutnya?",options:["Terima 65 sebagai jawaban benar karena hasil terakhir paling cermat, dan abaikan dua hasil 60 sebelumnya tanpa memeriksa ulang","Ambil rata-rata ketiganya (sekitar 61,7) sebagai jawaban akhir tanpa memeriksa perhitungan mana yang benar atau salah dalam ketiga percobaan","Periksa kembali perhitungan ketiga yang menghasilkan 65, karena dua hasil yang sama (60) lebih mungkin benar, tetapi tetap perlu diverifikasi"],answer:2,explain:"Hasil yang muncul lebih sering lebih mungkin benar, tetapi tetap perlu diverifikasi dengan menghitung ulang, bukan langsung dipercaya.",hint:"Apakah hasil yang muncul dua kali otomatis benar, ataukah tetap perlu diperiksa ulang?"},
{n:81,type:"open",micro:"Masalah nyata multi-langkah",q:"Sebuah kereta berangkat dari Jakarta pukul 08.00 menuju Bandung yang berjarak 150 km, dengan kecepatan rata-rata 75 km/jam. Pukul berapa kereta tersebut diperkirakan tiba di Bandung?",explain:"Menghitung waktu tempuh dari jarak dan kecepatan, lalu menambahkannya ke waktu keberangkatan, memberikan estimasi waktu tiba.",hint:"Hitung dulu waktu tempuhnya, lalu tambahkan ke waktu keberangkatan pukul 08.00.",sample:"Waktu tempuh = jarak ÷ kecepatan = 150 ÷ 75 = 2 jam. Karena berangkat pukul 08.00, kereta diperkirakan tiba pukul 10.00."},
{n:82,type:"open",micro:"Merancang cara memeriksa hasil",q:"Rancang cara cepat untuk memeriksa jawaban temanmu tentang kecepatan rata-rata suatu perjalanan, tanpa mengulang seluruh perhitungannya dari awal.",explain:"Mengalikan kembali kecepatan dengan waktu adalah cara verifikasi cepat tanpa mengulang seluruh metode.",hint:"Apakah mengalikan kembali kecepatan dan waktu akan menunjukkan jika jawaban temanmu salah?",sample:"Kalikan kembali kecepatan rata-rata yang mereka hitung dengan waktu tempuh yang diketahui — jika hasilnya cocok dengan jarak asli perjalanan, jawaban mereka kemungkinan besar benar; jika tidak cocok, ada yang perlu diperiksa ulang."},
{n:83,type:"open",micro:"Menyelidiki klaim yang tampak aneh",q:"Sebuah soal menyatakan dua mobil yang bergerak saling menjauh dengan kecepatan sama akan memiliki jarak yang bertambah dua kali lebih cepat dibandingkan jika hanya satu mobil yang bergerak. Seorang siswa merasa ini aneh. Bagaimana kamu menyelidiki klaim ini?",explain:"Mencoba dengan angka nyata mengungkap bahwa klaim tersebut memang benar, sesuai konsep kecepatan relatif untuk gerakan berlawanan arah.",hint:"Coba hitung dengan angka nyata: berapa pertambahan jarak per jam jika kedua mobil bergerak, dibandingkan jika hanya satu yang bergerak?",sample:"Mencoba dengan angka nyata: jika kedua mobil bergerak menjauh dengan kecepatan 50 km/jam masing-masing, jarak di antara keduanya bertambah 50+50=100 km setiap jam, dibandingkan hanya 50 km setiap jam jika hanya satu mobil yang bergerak sementara yang lain diam — ini mengonfirmasi klaim tersebut benar, karena kedua kecepatan saling menambah pada kecepatan relatif mereka."},
{n:84,type:"open",micro:"Koneksi sejarah/budaya",q:"Cari tahu (atau ingat kembali) bagaimana catatan waktu dan kecepatan digunakan dalam sejarah olahraga, seperti rekor lari atau balap, untuk membandingkan performa atlet dari era yang berbeda.",explain:"Menghubungkan konsep kecepatan-waktu dengan sejarah pencatatan rekor olahraga menunjukkan relevansi nyata konsep ini di luar kelas matematika.",hint:"Pernahkah kamu mendengar tentang rekor dunia lari 100 meter yang terus dipecahkan dari tahun ke tahun?",sample:"Rekor waktu lari (misalnya lari 100 meter) memungkinkan perbandingan performa atlet dari berbagai era secara objektif menggunakan angka yang sama (waktu tempuh untuk jarak yang sama), dan seiring waktu, rekor-rekor ini terus dipecahkan berkat peningkatan pelatihan, teknologi sepatu, dan lintasan — menunjukkan bagaimana konsep kecepatan dan waktu tempuh telah lama digunakan untuk mengukur kemajuan performa manusia secara terukur."},
{n:85,type:"open",micro:"Masalah nyata multi-langkah dengan pecahan",q:"Sebuah mobil menempuh 3/4 perjalanan sejauh 240 km dengan kecepatan 80 km/jam, lalu terjebak macet sehingga sisa perjalanan (1/4 lagi) hanya bisa ditempuh dengan kecepatan 20 km/jam. Berapa total waktu perjalanan tersebut?",explain:"Menghitung waktu untuk setiap tahap perjalanan secara terpisah, lalu menjumlahkannya, memberikan total waktu yang akurat.",hint:"Hitung jarak dan waktu untuk setiap tahap perjalanan secara terpisah, baru jumlahkan kedua waktu tersebut.",sample:"Jarak pertama = 3/4×240=180 km, waktu=180÷80=2,25 jam. Jarak sisa=60 km, waktu=60÷20=3 jam. Total waktu=2,25+3=5,25 jam (5 jam 15 menit)."},
{n:86,type:"open",micro:"Refleksi kesalahan",q:"Ceritakan pengalaman nyata ketika kamu membuat kesalahan terkait perhitungan kecepatan, jarak, atau waktu — misalnya salah rumus, atau lupa mengonversi satuan. Apa yang akan kamu lakukan secara berbeda sekarang?",explain:"Merefleksikan kesalahan nyata dengan perbaikan konkret menunjukkan keterampilan ini benar-benar sudah dipahami.",hint:"Ingat kembali momen ketika jawaban kecepatan, jarak, atau waktumu ternyata salah — apa yang sebenarnya salah?",sample:"Bersifat personal dan terbuka — tujuannya adalah mengenali penyebab nyata (seperti tertukar rumus, atau lupa mengonversi jam ke menit) dan menyebutkan perbaikan konkret, seperti selalu menuliskan rumus dan satuan secara eksplisit sebelum menghitung."},
{n:87,type:"open",micro:"Merancang proyek kelas",q:"Rancang proyek kelas sederhana untuk 30 siswa agar mempraktikkan konsep kecepatan, jarak, dan waktu menggunakan pengukuran nyata di lapangan sekolah.",explain:"Proyek yang menghubungkan pengukuran nyata dengan perhitungan kecepatan memberi latihan praktis yang bermakna.",hint:"Apakah mengukur waktu tempuh yang sesungguhnya dengan stopwatch akan membantu siswa memahami konsep ini secara nyata?",sample:"Minta kelompok kecil mengukur waktu yang dibutuhkan untuk berjalan atau berlari menempuh jarak tertentu (misalnya 50 meter) menggunakan stopwatch, menghitung kecepatan rata-rata masing-masing kelompok, lalu membandingkan hasil antar kelompok dan mendiskusikan faktor apa yang memengaruhi perbedaan kecepatan tersebut."},
{n:88,type:"open",micro:"Memperkirakan dan memverifikasi",q:"Perkirakan waktu tempuh untuk jarak 280 km dengan kecepatan 55 km/jam menggunakan perhitungan kasar di kepala, lalu verifikasi dengan perhitungan yang tepat.",explain:"Menerapkan teknik 'perkirakan dulu, verifikasi kemudian' pada perhitungan waktu tempuh yang nyata.",hint:"Bisakah membulatkan 55 menjadi 56 (yang lebih mudah dibagi ke 280) memberikan perkiraan kasar yang cukup dekat?",sample:"Perkiraan kasar: 280 dibagi 55 mendekati 280 dibagi 56 = 5, jadi waktunya sekitar 5 jam; verifikasi tepat: 280÷55≈5,09 jam, yang memang mendekati perkiraan kasar."},
{n:89,type:"open",micro:"Menyelidiki perbedaan hasil nyata",q:"Kamu dan seorang teman menghitung waktu tempuh yang sama, tetapi kalkulator temanmu menunjukkan hasil yang sedikit berbeda dari perhitunganmu secara manual. Berikan dua kemungkinan penjelasan, dan bagaimana cara memeriksa masing-masing.",explain:"Mempertimbangkan beberapa penyebab yang mungkin, dan cara memeriksa masing-masing, mencerminkan penalaran investigatif yang baik.",hint:"Bisakah perbedaan ini berasal dari kesalahan input, atau hanya dari pembulatan angka desimal yang berbeda?",sample:"Kemungkinan 1: kesalahan memasukkan angka jarak atau kecepatan ke dalam kalkulator — periksa ulang angka yang dimasukkan. Kemungkinan 2: perbedaan pembulatan angka desimal antara kalkulator dan perhitungan manual — bandingkan hasil keduanya menggunakan jumlah angka desimal yang sama."},
{n:90,type:"open",micro:"Koneksi statistik/rata-rata",q:"Sebuah laporan menyatakan 'rata-rata kecepatan kendaraan di jalan tol tersebut adalah 80 km/jam.' Mengapa angka rata-rata tunggal ini mungkin tidak menggambarkan kondisi lalu lintas di setiap waktu?",explain:"Menghubungkan pemahaman kecepatan dengan keterbatasan nyata dari sebuah angka rata-rata statistik.",hint:"Apakah mengetahui HANYA rata-rata kecepatan memberitahumu kondisi lalu lintas pada jam sibuk secara spesifik?",sample:"Rata-rata menggabungkan kecepatan kendaraan pada berbagai waktu berbeda menjadi satu angka — pada jam sibuk kecepatan bisa jauh lebih rendah karena macet, sementara pada malam hari bisa jauh lebih tinggi, sehingga rata-rata 80 km/jam tidak selalu mencerminkan kondisi lalu lintas pada waktu tertentu."},
{n:91,type:"open",micro:"Mini proyek",q:"Rancang dan selesaikan sebuah skenario kecepatan-jarak-waktu nyata (seperti merencanakan perjalanan, membandingkan dua kendaraan, atau menghitung waktu tiba), lalu tunjukkan langkah kerjamu dengan jelas.",explain:"Penerapan langsung keterampilan kecepatan-jarak-waktu pada tugas nyata yang dirancang sendiri adalah puncak pembelajaran skill ini.",hint:"Apakah menunjukkan setiap langkah kerjamu dengan jelas akan memudahkan orang lain memeriksa hasilnya?",sample:"Bersifat personal dan terbuka — tujuannya adalah mempraktikkan penerapan rumus kecepatan, jarak, dan waktu pada skenario realistis yang kamu rancang sendiri."},
{n:92,type:"open",micro:"Menjelaskan ke anak yang lebih muda",q:"Bagaimana kamu akan menjelaskan hubungan antara kecepatan, jarak, dan waktu kepada adik yang belum pernah mempelajarinya?",explain:"Menghubungkan konsep abstrak kecepatan-jarak-waktu dengan pengalaman konkret bersepeda menunjukkan pemahaman yang mendalam.",hint:"Bisakah pengalaman mengayuh sepeda lebih kencang menjadi contoh yang mudah dipahami untuk menjelaskan kecepatan?",sample:"Saya akan menggunakan contoh mengendarai sepeda — semakin cepat kamu mengayuh (kecepatan), semakin jauh kamu bisa pergi dalam waktu yang sama, atau semakin sedikit waktu yang kamu butuhkan untuk sampai ke tempat yang sama; ketiga hal ini (kecepatan, jarak, waktu) selalu saling berhubungan, dan jika kamu tahu dua di antaranya, kamu bisa menghitung yang ketiga."},
{n:93,type:"open",micro:"Refleksi alur Konkret-Piktorial-Abstrak",q:"Menurutmu, mengapa memulai dari pengalaman nyata (seperti membandingkan pelari cepat dan lambat) penting sebelum masuk ke rumus kecepatan yang abstrak?",explain:"Mencerminkan wawasan sejati tentang mengapa alur Konkret-Piktorial-Abstrak penting khususnya untuk konsep kecepatan.",hint:"Apakah rumus kecepatan akan lebih masuk akal bagi seseorang yang pernah mengalami langsung perbedaan cepat dan lambat, atau bagi yang hanya menghafal rumus?",sample:"Tanpa pengalaman nyata terlebih dahulu tentang bagaimana kecepatan sebenarnya terasa (melihat langsung siapa yang lebih cepat sampai tujuan, atau merasakan sendiri mengayuh sepeda lebih kencang), rumus abstrak seperti kecepatan=jarak÷waktu bisa terasa seperti sekadar angka yang harus dihafal, bukan sesuatu yang benar-benar menggambarkan seberapa cepat sesuatu bergerak — membangun dari pengalaman konkret dahulu membantu rumus tersebut menjadi masuk akal kemudian."},
{n:94,type:"open",micro:"Keputusan bisnis dengan kecepatan-jarak-waktu",q:"Sebuah perusahaan logistik menemukan bahwa mengoptimalkan rute pengiriman berdasarkan kecepatan rata-rata jalan yang berbeda-beda bisa menghemat waktu, tetapi membutuhkan data lalu lintas yang akurat dan selalu diperbarui. Keputusan bisnis apa yang mungkin didukung oleh hal ini, dan apa yang perlu diwaspadai?",explain:"Menerapkan penalaran kecepatan-jarak-waktu pada tradeoff bisnis nyata antara investasi data dan efisiensi jangka panjang.",hint:"Apakah rute yang dihitung dari data kecepatan yang sudah usang tetap bisa diandalkan?",sample:"Perusahaan mungkin memutuskan berinvestasi dalam sistem pemantauan lalu lintas real-time karena penghematan waktu pengiriman dalam jangka panjang bisa signifikan — tetapi perlu diwaspadai bahwa jika data kecepatan jalan yang digunakan sudah usang atau tidak akurat, rute yang direkomendasikan justru bisa lebih lambat daripada rute alternatif yang lebih sederhana."},
{n:95,type:"open",micro:"Membandingkan performa secara adil",q:"Tiga pelari menyelesaikan lomba lari dengan jarak berbeda dalam waktu yang berbeda pula: Pelari 1 menempuh 5 km dalam 25 menit, Pelari 2 menempuh 10 km dalam 55 menit, Pelari 3 menempuh 3 km dalam 14 menit. Bagaimana cara membandingkan performa ketiganya secara adil?",explain:"Membandingkan kecepatan rata-rata (bukan jarak atau waktu saja) adalah cara adil untuk membandingkan performa dengan jarak dan waktu yang berbeda-beda.",hint:"Karena jarak dan waktu ketiga pelari berbeda-beda, apakah kecepatan rata-rata (jarak÷waktu) lebih adil untuk dibandingkan daripada jarak atau waktu saja?",sample:"Karena jarak dan waktu ketiganya berbeda, cara yang adil adalah membandingkan kecepatan rata-rata masing-masing (jarak÷waktu): Pelari 1=5÷25=0,2 km/menit, Pelari 2=10÷55≈0,182 km/menit, Pelari 3=3÷14≈0,214 km/menit — menunjukkan Pelari 3 sebenarnya memiliki kecepatan rata-rata tertinggi, meskipun menempuh jarak terpendek."},
{n:96,type:"open",micro:"Batasan sebuah statistik",q:"Sebuah laporan menyatakan 'rata-rata waktu tempuh pengiriman paket suatu perusahaan adalah 2 hari.' Apa yang bisa diketahui dari angka ini, dan apa yang tidak bisa diketahui?",explain:"Mengenali bahwa sebuah statistik rata-rata memberi gambaran umum, tetapi bukan gambaran lengkap, adalah koneksi berpikir kritis yang penting.",hint:"Bisakah waktu pengiriman yang sangat bervariasi tetap menghasilkan rata-rata yang sama dengan waktu yang seragam?",sample:"Angka ini bisa menunjukkan kecepatan pengiriman secara umum — tetapi tidak menunjukkan apakah SEMUA paket dikirim dalam waktu yang seragam (semua sekitar 2 hari) atau sangat bervariasi (ada yang sangat cepat, ada yang sangat lambat) yang kebetulan rata-ratanya tetap 2 hari, sehingga tidak cukup untuk menilai keandalan pengiriman untuk paket tertentu."},
{n:97,type:"open",micro:"Investigasi nyata multi-langkah",q:"Rancang rencana untuk menentukan, menggunakan konsep kecepatan-jarak-waktu, moda transportasi mana (mobil, kereta, atau bus) yang paling cepat untuk perjalanan rutinmu, tanpa aplikasi navigasi digital.",explain:"Menerapkan strategi 'ukur beberapa kali, hitung rata-rata, bandingkan' pada perbandingan moda transportasi yang nyata.",hint:"Apakah mengukur waktu tempuh pada beberapa kesempatan berbeda (bukan hanya sekali) akan memberi perbandingan yang lebih adil?",sample:"Catat jarak perjalanan yang sama untuk setiap moda transportasi, catat waktu tempuh aktual masing-masing pada beberapa kesempatan berbeda (untuk memperhitungkan variasi lalu lintas), hitung kecepatan rata-rata masing-masing moda, lalu bandingkan hasilnya untuk menentukan mana yang secara konsisten paling cepat."},
{n:98,type:"open",micro:"Kecepatan-jarak-waktu dan teknologi",q:"Aplikasi navigasi digital dapat langsung menghitung estimasi waktu tiba tanpa kamu perlu menggunakan rumus kecepatan-jarak-waktu secara manual. Apa satu keuntungan dan satu risiko dari terlalu bergantung pada hal ini tanpa memahami cara kerja rumusnya?",explain:"Memperluas penalaran kecepatan-jarak-waktu ke alat digital nyata, menimbang kepraktisan melawan risiko kesalahan yang tidak terdeteksi.",hint:"Jika data lalu lintas yang digunakan aplikasi salah, akankah aplikasi tersebut memberi peringatan, atau tetap menampilkan estimasi yang percaya diri namun salah?",sample:"Keuntungan: estimasi waktu tiba yang mempertimbangkan kondisi lalu lintas real-time bisa didapat secara instan, jauh lebih akurat daripada perhitungan manual sederhana. Risiko: jika data lalu lintas aplikasi tersebut salah atau usang, kamu mungkin tidak menyadari estimasi yang ditampilkan sebenarnya tidak realistis, karena tidak memahami bagaimana angka tersebut seharusnya dihitung."},
{n:99,type:"open",micro:"Menyelidiki angka yang berbeda",q:"Dua aplikasi navigasi menunjukkan estimasi waktu tempuh yang sedikit berbeda untuk rute yang sama, misalnya 45 menit dan 52 menit. Bagaimana seharusnya pembaca yang cermat menyikapi perbedaan ini?",explain:"Menerapkan penalaran investigatif yang adil terhadap angka yang tampak bertentangan, tanpa langsung menuduh salah satu sumber keliru.",hint:"Bisakah dua aplikasi navigasi menyarankan rute yang sedikit berbeda, sehingga menghasilkan estimasi waktu yang berbeda pula?",sample:"Pembaca yang cermat sebaiknya mempertimbangkan bahwa kedua aplikasi mungkin menggunakan data lalu lintas real-time yang sedikit berbeda, atau memilih rute yang sedikit berbeda pula, alih-alih langsung menganggap salah satu aplikasi pasti keliru, dan bisa memeriksa rute yang disarankan masing-masing aplikasi sebelum memutuskan mana yang lebih sesuai."},
{n:100,type:"open",micro:"Refleksi kapstone",q:"Melihat kembali keterampilan Kecepatan-Jarak-Waktu ini — mulai dari membandingkan pelari cepat dan lambat secara nyata, lalu ke grafik dan tabel jarak-waktu, hingga akhirnya ke rumus kecepatan, kecepatan rata-rata, dan kecepatan relatif yang abstrak — kebiasaan apa yang sekarang kamu miliki ketika menghadapi soal tentang kecepatan, jarak, atau waktu?",explain:"Menyebutkan kebiasaan baru yang konkret, terkait perjalanan konkret-ke-abstrak dari skill ini, adalah tanda paling jelas bahwa keterampilan ini sudah tertanam.",hint:"Ingat momen dalam unit ini ketika soal kecepatan-jarak-waktu berhenti membutuhkan cerita nyata dan mulai masuk akal sebagai rumus abstrak tersendiri.",sample:"Bersifat personal dan terbuka — carilah perubahan nyata, seperti secara otomatis menuliskan rumus yang tepat sebelum menghitung, memeriksa hasil dengan mengalikan kembali kecepatan dan waktu, atau langsung menyadari satuan yang perlu dikonversi sebelum menghitung."},
];
